"""Debian package version comparison. See task.md."""

from __future__ import annotations

import string
from functools import cmp_to_key
from typing import NamedTuple


class VersionError(ValueError):
    """Raised for a string that is not a valid Debian version."""


class _Version(NamedTuple):
    epoch: int
    upstream: str
    revision: str


_DIGITS = frozenset(string.digits)
_LETTERS = frozenset(string.ascii_letters)
_ALNUM = _DIGITS | _LETTERS
_UPSTREAM_CHARS = _ALNUM | frozenset(".+~-:")
_REVISION_CHARS = _ALNUM | frozenset(".+~")


def _parse(text: str) -> _Version:
    epoch = 0
    rest = text
    if ":" in text:
        epoch_text, rest = text.split(":", 1)
        if not epoch_text or not _DIGITS.issuperset(epoch_text):
            raise VersionError(f"invalid epoch in {text!r}")
        epoch = int(epoch_text)

    upstream, revision = rest, "0"
    if "-" in rest:
        upstream, revision = rest.rsplit("-", 1)
        if not revision or not _REVISION_CHARS.issuperset(revision):
            raise VersionError(f"invalid revision in {text!r}")

    if not upstream or upstream[0] not in _DIGITS or not _UPSTREAM_CHARS.issuperset(upstream):
        raise VersionError(f"invalid upstream version in {text!r}")
    return _Version(epoch, upstream, revision)


def _weight(c: str) -> int:
    if c == "~":
        return -1
    if c in _LETTERS:
        return ord(c)
    return 256 + ord(c)


def _cmp_part(a: str, b: str) -> int:
    i = j = 0
    while True:
        while True:
            ca = _weight(a[i]) if i < len(a) and a[i] not in _DIGITS else 0
            cb = _weight(b[j]) if j < len(b) and b[j] not in _DIGITS else 0
            if ca != cb:
                return -1 if ca < cb else 1
            if ca == 0:
                break
            i += 1
            j += 1

        start_a, start_b = i, j
        while i < len(a) and a[i] in _DIGITS:
            i += 1
        while j < len(b) and b[j] in _DIGITS:
            j += 1
        da = a[start_a:i].lstrip("0")
        db = b[start_b:j].lstrip("0")
        if len(da) != len(db):
            return -1 if len(da) < len(db) else 1
        if da != db:
            return -1 if da < db else 1
        if i == len(a) and j == len(b):
            return 0


def _cmp_versions(x: _Version, y: _Version) -> int:
    if x.epoch != y.epoch:
        return -1 if x.epoch < y.epoch else 1
    return _cmp_part(x.upstream, y.upstream) or _cmp_part(x.revision, y.revision)


def compare(a: str, b: str) -> int:
    """Return -1, 0 or 1 as `a` sorts before, equal to, or after `b`."""
    return _cmp_versions(_parse(a), _parse(b))


def sort_versions(versions: list[str]) -> list[str]:
    """Return `versions` in ascending order; equal versions keep their input order."""
    parsed = [(_parse(v), v) for v in versions]
    parsed.sort(key=cmp_to_key(lambda x, y: _cmp_versions(x[0], y[0])))
    return [v for _, v in parsed]
